from functools import lru_cache

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        @lru_cache(None)
        def dp(L: int, rem_sum: int, prod_mod: int, target_sum: int) -> int:
            # Prune impossible remaining sums early
            if rem_sum < 0 or rem_sum > L * 9:
                return 0
            if L == 0:
                return 1 if prod_mod == 0 else 0

            ans = 0
            for d in range(min(10, rem_sum + 1)):
                ans += dp(L - 1, rem_sum - d, (prod_mod * d) % target_sum, target_sum)
            return ans

        def count_up_to(n: int) -> int:
            if n <= 0:
                return 0

            s_n = str(n)
            length = len(s_n)
            total = 0
            max_target = 9 * length

            for target_sum in range(1, max_target + 1):
                # 1. Evaluate valid combinations for numbers with strictly fewer digits
                for L in range(1, length):
                    for d in range(1, 10):
                        if target_sum >= d:
                            total += dp(L - 1, target_sum - d, d % target_sum, target_sum)

                # 2. Evaluate valid combinations for numbers with the exact same number of digits
                cur_sum = 0
                cur_prod = 1 % target_sum
                for i in range(length):
                    limit = int(s_n[i])
                    start = 1 if i == 0 else 0

                    for d in range(start, limit):
                        if target_sum >= cur_sum + d:
                            total += dp(length - 1 - i, target_sum - cur_sum - d, (cur_prod * d) % target_sum, target_sum)

                    # Proceed with the limit digit itself to evaluate further prefixes
                    cur_sum += limit
                    cur_prod = (cur_prod * limit) % target_sum

                    # If prefix sum has already exceeded the target, safely break
                    if cur_sum > target_sum:
                        break
                else:
                    # 3. Check the number n itself if it reached the end perfectly
                    if cur_sum == target_sum and cur_prod == 0:
                        total += 1

            return total

        return count_up_to(r) - count_up_to(l - 1)
